Here is the Arduino sketch that blinks the LED on pin 13 every half second using `millis()` for non-blocking timing.

MAKE CODE: Blink Non-Blocking
language arduino
// Blink LED on pin 13 every 500ms without using delay().
// Uses millis() to track time so the loop can do other work.

const int ledPin = 13;          // Pin 13 is the built-in LED on most Arduinos
const unsigned long interval = 500; // Time between blinks in milliseconds

unsigned long previousMillis = 0; // Stores the last time the LED changed state
bool ledState = LOW;              // Current state of the LED

void setup() {
  pinMode(ledPin, OUTPUT);      // Set the LED pin as an output
  digitalWrite(ledPin, LOW);    // Start with LED off
}

void loop() {
  unsigned long currentMillis = millis(); // Get the current time

  // Check if enough time has passed since the last change
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;       // Update the last time the LED changed
    ledState = !ledState;                 // Toggle the LED state (HIGH to LOW or LOW to HIGH)
    digitalWrite(ledPin, ledState);       // Apply the new state to the pin
  }

  // Other code can go here without blocking the timing logic
}
END

Here is the Arduino sketch for your stepper motor setup using the AccelStepper library to ensure smooth acceleration and deceleration.

MAKE CODE: Stepper BackAndForth
language arduino
// Stepper motor on A4988 driver (STEP on pin 3, DIR on pin 2)
// Moves 800 steps forward and back repeatedly with smooth acceleration.
// Wiring:
//   STEP -> Pin 3
//   DIR  -> Pin 2
//   ENABLE -> Pin 4 (Optional: connect to GND to enable, or use this pin to disable)
//   VDD  -> 5V (Logic power)
//   GND  -> GND
//   VMOT -> Motor supply (e.g., 12V)
//   MS1, MS2, MS3 -> Set microstepping (e.g., GND for full step, or as per driver)
//
// Note: Ensure the A4988 current limit is set correctly for your motor.
// This sketch assumes a standard 200-step/rev motor. 800 steps = 4 full revolutions.

#include <AccelStepper.h>

// Define pins
const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 4; // Optional: Set to LOW to enable driver, HIGH to disable

// Configuration
const long stepsPerMove = 800; // Number of steps to move forward/back
const long maxSpeed = 1000;    // Maximum speed in steps per second
const long acceleration = 500; // Acceleration in steps per second squared

// Create an instance of AccelStepper
// DRIVER mode is used for step/dir drivers like A4988
AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  // Initialize the enable pin if used
  pinMode(enablePin, OUTPUT);
  digitalWrite(enablePin, LOW); // Enable the driver (LOW is usually active)

  // Set maximum speed and acceleration
  stepper.setMaxSpeed(maxSpeed);
  stepper.setAcceleration(acceleration);

  // Move to the first target (800 steps forward from current position)
  // We start at 0, so we move to 800
  stepper.moveTo(stepsPerMove);
}

void loop() {
  // Run the stepper
  // The run() function must be called frequently (no delay() inside loop)
  // It returns true if the stepper has reached its target
  if (stepper.run()) {
    // Once the target is reached, reverse direction
    // Calculate the new target: current position - 2 * stepsPerMove
    // This moves back to the start (0) and then continues to -800 if we wanted,
    // but here we want to go back to 0 and then forward again.
    // Actually, to go back and forth between 0 and 800:
    // If we are at 800, we want to go to 0.
    // If we are at 0, we want to go to 800.

    long currentPos = stepper.currentPosition();

    if (currentPos >= stepsPerMove) {
      // Reached the forward limit, go back to 0
      stepper.moveTo(0);
    } else if (currentPos <= 0) {
      // Reached the backward limit, go forward to 800
      stepper.moveTo(stepsPerMove);
    }
  }
}
END

Here is the P1AM-100 sketch for the motor start/stop circuit with a seal-in logic, using the specified inputs and outputs.

MAKE CODE: Motor Start/Stop Seal-in
language arduino
// P1AM-100: Motor Start/Stop with Seal-in Logic
// Slot 1: Discrete Input Module
//   Channel 1: Start Button (Normally Open)
//   Channel 2: Stop Button (Normally Closed)
// Slot 2: Discrete Output Module
//   Channel 1: Motor Contactor
#include <P1AM.h>

const int inSlot = 1;
const int outSlot = 2;
bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  // Wait for the P1AM modules to initialize
  while (!P1.init()) {
    ;
  }
}

void loop() {
  // Read inputs
  // Start is NO: reads HIGH (true) when pressed
  bool startPressed = P1.readDiscrete(inSlot, 1);

  // Stop is NC: reads LOW (false) when pressed (circuit open)
  // We invert the logic so 'stopPressed' is true when the button is actually pressed/stopped
  bool stopPressed = !P1.readDiscrete(inSlot, 2);

  // Seal-in Logic:
  // Motor runs if: (Start is pressed OR Motor is already running)
  // AND: (Stop is NOT pressed)
  motorRunning = (startPressed || motorRunning) && !stopPressed;

  // Write output
  // Turn on the motor contactor if motorRunning is true
  P1.writeDiscrete(motorRunning, outSlot, 1);
}
END

MAKE CODE: Average temperature from CSV
python
import csv
import sys

def main():
    if len(sys.argv) < 2:
        print("usage: python3 avg_temp.py readings.csv")
        return

    temps = []
    try:
        with open(sys.argv[1], newline="") as f:
            reader = csv.DictReader(f)
            for row in reader:
                try:
                    # Extract the 'temp' column and convert to float
                    val = float(row['temp'])
                    temps.append(val)
                except (KeyError, ValueError):
                    # Skip rows missing 'temp' or with non-numeric values
                    continue

        if not temps:
            print("No valid temperature data found.")
            return

        average = sum(temps) / len(temps)
        print(f"Average temperature: {average}")

    except FileNotFoundError:
        print(f"Error: File '{sys.argv[1]}' not found.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
END

